/* ── Global handlers ─────────────────────────────────────────────────── */
window._rattrapage_investiguer = function(tache, client) {
    var dlg = new frappe.ui.Dialog({
        title: '\ud83d\udd0d Investiguer \u2014 ' + (client || tache),
        fields: [{ fieldname: 'note', fieldtype: 'Small Text', label: "Note d'investigation", reqd: 1 }],
        primary_action_label: 'Enregistrer',
        primary_action: function(vals) {
            frappe.call({
                method: 'customization_app.api.save_investigation_note',
                args: { tache: tache, note: vals.note },
                callback: function(r) {
                    if (r.message) {
                        frappe.show_alert({ message: 'Note enregistr\u00e9e \u2705', indicator: 'green' }, 3);
                        dlg.hide();
                        frappe.query_report.refresh();
                    }
                },
            });
        },
    });
    dlg.show();
};

window._rattrapage_planner = function(tache, client) {
    if (!client) { frappe.show_alert({ message: 'Client non d\u00e9fini', indicator: 'red' }, 3); return; }
    // Store source tache — will be marked planifié only when RDV is actually saved
    localStorage.setItem('rdv_source_tache', tache);
    frappe.call({
        method: 'customization_app.api.get_customer_info_all',
        args: { customer: client },
        callback: function(r) {
            var info = r.message || {};
            localStorage.setItem('rdv_prefill', JSON.stringify({
                custom_client: client, secteur: info.secteur || '', _addresses: info.addresses || [],
            }));
            if (typeof window.rdvLibre_openOverlay === 'function') {
                window.rdvLibre_openOverlay();
            } else {
                frappe.show_alert({ message: 'Rechargez la page et r\u00e9essayez', indicator: 'orange' }, 4);
            }
        },
    });
};

/* ── Card renderer ──────────────────────────────────────────────────── */

/* ── Aide contextuelle (economiq only) ────────────────────────────────────── */
function _econo_help(storageKey, title, items) {
    if (frappe.session.user !== 'economiqaquasolutions23@gmail.com') return $();
    if (localStorage.getItem(storageKey) === 'hidden') return $();
    var $existing = $('#' + storageKey);
    if ($existing.length) return $existing;
    var collapsed = localStorage.getItem(storageKey + '_c') === '1';
    var html = '<ul style="margin:4px 0 0 2px;padding-left:16px;">'
        + items.map(function(it) {
            return '<li style="font-size:12px;color:#444;line-height:1.6;margin:2px 0;">'
                + it.icon + ' <strong>' + it.label + '</strong>'
                + (it.desc ? ' — ' + it.desc : '')
                + '</li>';
        }).join('')
        + '</ul>';
    var $b = $("<div id='" + storageKey + "' style='background:linear-gradient(135deg,#e8f5fd,#f0f9ff);border:1px solid #90caf9;border-radius:10px;padding:10px 14px;margin-bottom:12px;box-shadow:0 2px 6px rgba(0,100,200,0.08);'><div style='display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;'><strong style='font-size:12px;color:#1565c0;'>💡 " + title + "</strong><div style='display:flex;gap:12px;'><button class='_ht' style='font-size:11px;color:#1565c0;background:none;border:none;cursor:pointer;padding:0;'>" + (collapsed ? '▶ Afficher' : '▼ Réduire') + "</button><button class='_hc' style='font-size:11px;color:#aaa;background:none;border:none;cursor:pointer;padding:0;'>✕ Fermer</button></div></div><div class='_hb' style='display:" + (collapsed ? "none" : "block") + ";'>" + html + "</div></div>");
    $b.find('._ht').on('click', function() { var $bd = $b.find('._hb'); var v = $bd.is(':visible'); $bd.toggle(); $(this).text(v ? '▶ Afficher' : '▼ Réduire'); localStorage.setItem(storageKey + '_c', v ? '1' : '0'); });
    $b.find('._hc').on('click', function() { localStorage.setItem(storageKey, 'hidden'); $b.fadeOut(200, function() { $b.remove(); }); });
    return $b;
}

window._rattrapage_render_cards = function() {
    if (frappe.query_report && frappe.query_report.$report) { var $__h = _econo_help('help_rattrapage','Guide — Rapport Appels Rattrapage',[{icon:'📋',label:'Les cartes',desc:'Chaque carte représente un client dont le rendez-vous a été annulé ou manqué et qui doit être rattrapé.'},{icon:'📝',label:'Sujet (ligne bleue)',desc:'Le titre du rendez-vous original — ex: Entretien osmoseur, Livraison, etc.'},{icon:'❌',label:'Raison annulation (badge jaune)',desc:'Pourquoi le RDV a été annulé — ex: Client non joignable, Retard, etc.'},{icon:'✅',label:'Badge Remise (badge vert/or)',desc:'Ce client a une autorisation de remise. Vous pouvez proposer jusqu\'à 10% de réduction pour vous excuser du retard Aquaworld — pas systématiquement, seulement si le client semble hésitant. Notez la remise accordée dans la note du prochain rendez-vous.'},{icon:'📋',label:'Rapport (dernière ligne)',desc:'Note laissée par le technicien ou lors d\'une investigation précédente — résumé de ce qui s\'est passé avec ce client.'},{icon:'🔍',label:'Investiguer',desc:'Le client a été rappelé mais ne souhaite pas reprendre RDV → notez ses commentaires. La tâche passe en Investigué et disparaît du rapport.'},{icon:'📅',label:'Planifier',desc:'Le client a été rappelé et souhaite reprendre RDV → ouvre le calendrier avec le client pré-rempli. Après avoir enregistré le RDV, la tâche passe en planifié.'}]); if ($__h && $__h.length) frappe.query_report.$report.before($__h); }

    var data = (frappe.query_report && frappe.query_report.data) || [];
    var $wrapper = frappe.query_report.$report;
    if (!$wrapper || !$wrapper.length) return;

    /* Inject CSS once to permanently hide the datatable */
    if (!document.getElementById('rattrapage-hide-style')) {
        var style = document.createElement('style');
        style.id = 'rattrapage-hide-style';
        style.textContent = '.report-wrapper { display: none !important; }';
        document.head.appendChild(style);
    }

    /* Remove old container on refresh */
    $('#rattrapage-cards').remove();
    var $container = $('<div id="rattrapage-cards" style="padding:4px 0"></div>');
    $wrapper.before($container);

    if (!data.length) {
        $container.html('<div style="text-align:center;color:#6b7280;padding:60px 0;font-size:14px">\u2705 Aucune t\u00e2che \u00e0 rattraper</div>');
        return;
    }

    /* ── Statistics ── */
    var total     = data.length;
    var cancelled = data.filter(function(d){ return d.status === 'Cancelled'; }).length;
    var open      = data.filter(function(d){ return d.status === 'Open'; }).length;

    /* secteur counts */
    var secteurMap = {};
    data.forEach(function(d){
        var s = d.secteur || 'N/A';
        secteurMap[s] = (secteurMap[s] || 0) + 1;
    });
    var secteurList = Object.keys(secteurMap).sort(function(a,b){ return secteurMap[b]-secteurMap[a]; });
    var secteurBars = secteurList.map(function(s){
        var pct = Math.round(secteurMap[s]/total*100);
        return '<div style="display:flex;align-items:center;gap:8px;min-width:130px">'
            + '<span style="font-size:11px;color:#374151;width:64px;text-align:right;white-space:nowrap">' + s + '</span>'
            + '<div style="flex:1;background:#e5e7eb;border-radius:4px;height:8px;min-width:60px">'
            +   '<div style="background:#2490ef;width:' + pct + '%;height:8px;border-radius:4px"></div>'
            + '</div>'
            + '<span style="font-size:11px;color:#6b7280;width:28px">' + secteurMap[s] + '</span>'
            + '</div>';
    }).join('');

    var statsHtml =
        '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px 18px;margin-bottom:12px">'
        + '<div style="display:flex;align-items:flex-start;gap:24px;flex-wrap:wrap">'
        /* counters */
        + '<div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap">'
        +   '<div style="text-align:center">'
        +     '<div style="font-size:28px;font-weight:700;color:#1f2937;line-height:1">' + total + '</div>'
        +     '<div style="font-size:11px;color:#6b7280;margin-top:2px">Total</div>'
        +   '</div>'
        +   '<div style="width:1px;height:36px;background:#e5e7eb"></div>'
        +   '<div style="text-align:center">'
        +     '<div style="font-size:22px;font-weight:700;color:#dc2626;line-height:1">' + cancelled + '</div>'
        +     '<div style="font-size:11px;color:#6b7280;margin-top:2px">Cancelled</div>'
        +   '</div>'
        +   '<div style="text-align:center">'
        +     '<div style="font-size:22px;font-weight:700;color:#d97706;line-height:1">' + open + '</div>'
        +     '<div style="font-size:11px;color:#6b7280;margin-top:2px">Open</div>'
        +   '</div>'
        + '</div>'
        /* secteur bars */
        + '<div style="display:flex;flex-direction:column;gap:4px;border-left:1px solid #e5e7eb;padding-left:20px">'
        +   '<div style="font-size:11px;font-weight:600;color:#374151;margin-bottom:2px">\ud83d\udccd Par secteur</div>'
        +   secteurBars
        + '</div>'
        + '</div>'
        + '</div>';

    /* ── Cards ── */
    var cardsHtml = '';
    data.forEach(function(d) {
        var tache   = d.name   || '';
        var client  = d.custom_client || '';
        var nom     = d.nom_client    || client;
        var tel     = d.tel           || '\u2014';
        var type_i  = d.custom_type_dintervention || '';
        var status  = d.status        || '';
        var secteur = d.secteur       || '';
        var raison  = d.raison_annulation || '';
        var rapport = d.rapport_visite    || '';
        var subject = d.subject            || '';
        var date    = (d.starts_on || '').substring(0, 16).replace('T', ' ');
        var remise  = d.autorisation_remise || 'Non';

        var statusColor = status === 'Cancelled' ? '#dc2626' : '#d97706';
        var statusBg    = status === 'Cancelled' ? '#fee2e2' : '#fef3c7';
        var remiseBadge = remise === 'Oui'
            ? '<span style="background:#fef3c7;color:#92400e;padding:1px 7px;border-radius:10px;font-size:10px;font-weight:600">\u2713 Remise</span>'
            : '';

        var te = tache.replace(/'/g, "\\'").replace(/"/g, '&quot;');
        var ce = client.replace(/'/g, "\\'").replace(/"/g, '&quot;');

        var btnI = '<button style="background:#0891b2;color:#fff;border:none;border-radius:4px;padding:2px 10px;cursor:pointer;font-size:11px;font-weight:500;white-space:nowrap" '
            + 'onclick="window._rattrapage_investiguer(\'' + te + '\',\'' + ce + '\')">\ud83d\udd0d Investiguer</button>';
        var btnP = '<button style="background:#2490ef;color:#fff;border:none;border-radius:4px;padding:2px 10px;cursor:pointer;font-size:11px;font-weight:500;white-space:nowrap" '
            + 'onclick="window._rattrapage_planner(\'' + te + '\',\'' + ce + '\')">\ud83d\udcc5 Planner</button>';

        cardsHtml +=
            '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:10px 16px;margin:5px 0;box-shadow:0 1px 3px rgba(0,0,0,.05)">'
            + '<div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap">'
            +   '<a href="/app/tache-de-travail/' + tache + '" style="font-weight:700;font-size:13px;color:#1f2937;text-decoration:none" target="_blank">' + tache + '</a>'
            +   '<span style="font-weight:600;font-size:13px;color:#2490ef">' + nom + '</span>'
            +   '<span style="color:#6b7280;font-size:12px">\ud83d\udcde ' + tel + '</span>'
            +   '<span style="background:' + statusBg + ';color:' + statusColor + ';padding:1px 8px;border-radius:10px;font-size:10px;font-weight:700">' + status + '</span>'
            +   remiseBadge
            +   btnI + btnP
            + '</div>'
            + '<div style="display:flex;gap:14px;flex-wrap:wrap;font-size:11px;color:#6b7280;margin-top:5px">'
            +   (type_i  ? '<span>\ud83d\udd27 ' + type_i  + '</span>' : '')
            +   (secteur ? '<span>\ud83d\udccd ' + secteur + '</span>' : '')
            +   (date    ? '<span>\ud83d\uddd3 ' + date    + '</span>' : '')
            + '</div>'
            + (subject ? '<div style="font-size:11px;color:#1e40af;background:#eff6ff;border-radius:4px;padding:2px 8px;margin-top:5px;display:inline-block">\ud83d\udcdd ' + subject + '</div>' : '')
            + (raison  ? '<div style="font-size:11px;color:#92400e;background:#fef3c7;border-radius:4px;padding:2px 8px;margin-top:5px;display:inline-block">\u274c ' + raison + '</div>' : '')
            + (rapport ? '<div style="font-size:11px;color:#374151;margin-top:5px;white-space:pre-wrap">\ud83d\udccb ' + rapport + '</div>' : '')
            + '</div>';
    });

    $container.html(statsHtml + cardsHtml);
};

/* ── Report definition ────────────────────────────────────────────────── */
frappe.query_reports['Liste Appels Rattrapage'] = {
    after_datatable_render: function(dt) {
        window._rattrapage_render_cards();
    },
};
